mapper.select:
select category_id, count(1) count, count(s.id) as practice_count, sum(s.solved) as solved_count
from oj_practice_theory t left join oj_practice_solved s on t.resource_id = s.practice_id
where t.practice_set_id in

    #{setId}

and t.`public` = 1 and s.submit_user_id = #{userId}
group by t.category_id
